export type QACategory =
  | "aqida"      // Основы веры
  | "salah"      // Намаз
  | "tahara"     // Очищение
  | "sawm"       // Пост
  | "zakat"      // Закят
  | "hajj"       // Хадж и Умра
  | "family"     // Семья и брак
  | "halal"      // Халяль / харам
  | "ethics"     // Этика и нравственность
  | "modern";    // Современные вопросы

export interface QACategoryInfo {
  key: QACategory;
  name: string;
  emoji: string;
  color: string;
}

