    a: "Да, достоверно передано, что кто совершит вуду хорошо, а затем скажет шахаду, тому откроются все восемь врат Рая, и он войдёт в любые из них. Желательно добавлять: «Аллахумма-джальни мина-т-таввабина ва-джальни мина-ль-мутатаххирин».",
