    a: "По одному сильному мнению (Ибн Таймия, ханафиты) земля очищается высыханием следа нечистоты солнцем и ветром, если исчезли цвет и запах, и на этом месте можно молиться. По другим — нужна вода. Для молитвы на такой земле высыхание достаточно.",
