    a: "Обязательно лишь довести воду до всего тела; порядок в гусле не является фардом. Можно полностью погрузиться в воду (море, бассейн, ванну) один раз с намерением, и джанаба снимется. Описанный порядок (голова, правая, левая сторона) — сунна для совершенства.",
