    a: "Пометка «может содержать следы» указывает на возможность перекрёстного контакта, а не на наличие свинины в составе. Если в самом составе свинины нет, пища дозволена, так как основа — дозволенность, а предположение о следах не делает продукт запретным. При явном указании свинины в составе — воздержаться и выбрать halal/veg меню.",
