    a: "Работа, прямо обслуживающая производство, перевозку или сбыт алкоголя, запретна, ведь Пророк ﷺ проклял в связи с вином и того, кто его перевозит, и того, кому везут. Должность, являющаяся звеном цепочки алкогольного бизнеса, входит в помощь греху. Работа, вовсе не связанная с алкогольным продуктом, оценивается отдельно, но лучше сменить.",
