    q: "Нарушают ли намаз лишние движения, например поправить одежду?",
    a: "Небольшие, немногочисленные движения по нужде (поправить одежду, почесаться, сдвинуть ребёнка) намаз не нарушают. Нарушает его лишь много последовательных посторонних движений, не связанных с намазом; фиксированного числа в достоверных текстах нет, хотя часть учёных ориентируется на «три и более подряд». Пророк ﷺ носил внучку на руках в намазе.",
    source: "Бухари, Муслим (хадис о ношении Умамы в намазе)",
    scholar: "Постоянный комитет (Ляджна ад-Даима)",
