    category: "salah",
    q: "Можно ли молиться, когда сильно хочется в туалет?",
    a: "Молиться при сильной нужде порицается (макрух), так как это разрушает смирение. Пророк ﷺ запретил намаз при позывах и при наличии готовой еды во время голода. Сначала облегчись, затем молись спокойно; если время поджимает — совершай, но такой намаз неполноценен.",
    source: "Муслим (хадис: «Нет полноценного намаза при готовой еде и когда сдерживают два вида нужды»)",
