    a: "Дуа истифтах (например, «Субханака-Ллахумма…» или «Аллахумма бā‘ид байни…») — подтверждённая сунна, читаемая тихо после вступительного такбира и до Фатихи. Её пропуск не портит намаз и не требует саджда сахв. Есть несколько достоверных её вариантов.",
    source: "Бухари, Муслим (варианты дуа истифтах Пророка ﷺ)",
    scholar: "Ибн Усаймин",
