    id: 646,
    category: "salah",
    q: "Можно ли восполнить пропущенную сунну Зухра после фарда?",
    a: "Да, кто не успел совершить сунну до Зухра из-за икамы, может совершить её после фарда. Также после Зухра есть подтверждённые 2 раката раватиб. Восполнение упущенных раватиб — сунна, а не обязанность, но желательно.",
    source: "Тирмизи (хадис о восполнении двух ракатов после Зухра); Бухари",
