    id: 726,
    category: "sawm",
    q: "Обязателен ли пост при итикафе?",
    a: "По ханафитам и маликитам пост — условие итикафа; по шафиитам и в одном из мнений ханбалитов итикаф действителен и без поста. Поэтому итикаф допустим и вне Рамадана, хотя лучшее время — постящиеся дни Рамадана.",
