    category: "aqida",
    q: "Обязательна ли вера в Хранимую Скрижаль (аль-Лявх аль-Махфуз)?",
    a: "Да, вера в аль-Лявх аль-Махфуз — часть веры в предопределение и Писания. В нём Аллах записал всё сущее до Судного дня. Аллах говорит: «Это — славный Коран в Хранимой Скрижали». Мы верим в его существование, не постигая его образа.",
    source: "Коран 85:21-22",
    scholar: "Ибн Касир",
