    q: "Что такое махр и обязателен ли он?",
    a: "Махр — это обязательный дар мужа жене, её собственность. Аллах говорит: «Давайте женщинам их брачный дар от чистой души». Без назначения махра брак заключить можно, но выплата всё равно становится обязательной (махр аль-мисль), равный махру подобных ей женщин.",
