    category: "family",
    q: "Сколько кормлений создают молочное родство?",
    a: "Разногласие: по шафиитам и ханбалитам необходимо минимум пять насыщающих кормлений (как в хадисе Аиши). По ханафитам и маликитам достаточно любого попадания молока в желудок ребёнка. Все согласны, что кормление должно быть до двух лет.",
