    category: "family",
    q: "Что важнее — послушание мужу или родителям для замужней женщины?",
    a: "После замужества первостепенное право над женщиной переходит к мужу в делах семейной жизни, но она не перестаёт быть обязанной почитать родителей и поддерживать с ними связь. Муж не вправе запрещать ей навещать родителей и рвать родственные узы.",
