    category: "family",
    q: "Как поддерживать связь с родственником, который плохо ко мне относится?",
    a: "Истинное поддержание уз — не отвечать тем же, а быть добрым к тому, кто рвёт с тобой. Пророк ﷺ сказал: «Соединяющий узы — не тот, кто отвечает взаимностью, а тот, кто восстанавливает связь, когда её рвут». Награда за терпение к такой родне велика.",
