    a: "Нужно покаяться перед Аллахом, прекратить и сожалеть. По поводу самого человека учёные разошлись: если сообщение ему о гыбе не вызовет большей вражды — лучше попросить прощения; если вызовет — достаточно поминать его добром, просить за него прощения у Аллаха и хвалить его в тех собраниях, где о нём злословили.",
