    a: "Таваду — это смирение перед истиной и мягкость к людям без унижения себя. Проявляется в том, чтобы принимать правду от любого, приветствовать бедных, сидеть с простыми людьми, самому помогать по дому. Пророк чинил обувь, доил овец и служил своей семье.",
