    category: "ethics",
    q: "Можно ли плакать при потере близкого — не противоречит ли это терпению?",
    a: "Слёзы и печаль сердца дозволены и не противоречат терпению; Пророк плакал при смерти сына Ибрахима. Запрещено то, что делает язык и руки: причитания, вопли, разрывание одежды и битьё по щекам. Терпение — при первом ударе горя.",
    source: "Бухари",
    scholar: "Ан-Навави",
