    q: "Почему важно благодарить людей, а не только Аллаха?",
    a: "Пророк (мир ему) сказал: «Не благодарен Аллаху тот, кто не благодарит людей». Благодарность человеку — часть благодарности Аллаху, который сделал его причиной блага. Кто сделал вам добро — воздайте ему тем же или сделайте дуа за него.",
    source: "Абу Дауд, Тирмизи",
    scholar: "Аль-Альбани",
