    category: "ethics",
    q: "Кто по-настоящему сильный человек согласно исламу?",
    a: "Пророк (мир ему) сказал: «Силён не тот, кто побеждает в борьбе, а тот, кто владеет собой во время гнева». Настоящая сила — в самообладании, а не в физической мощи. Сдерживающих гнев Аллах назвал в числе богобоязненных.",
    source: "Бухари, Муслим",
    scholar: "Мнение большинства учёных",
