    category: "hajj",
    q: "Что будет, если муж и жена вступят в близость во время ихрама хаджа?",
    a: "Половая близость до первого освобождения (перед рами и бритьём в день Курбана) портит хадж; его надо довести до конца, возместить в следующем году и принести в жертву верблюда/корову. Это тяжелейшее нарушение ихрама.",
    source: "Коран 2:197",
    scholar: "Мнение большинства учёных",
