/** Total count */
export const QA_TOTAL = QA_LIST.length;

/** Get random Q&A */
export function getRandomQA(): QA {
  return QA_LIST[Math.floor(Math.random() * QA_LIST.length)];
}

/** Get Q&A of the day (stable for the day) */
export function getQAOfTheDay(today: Date = new Date()): QA {
  const dayIdx = Math.floor(today.getTime() / (1000 * 60 * 60 * 24));
  return QA_LIST[dayIdx % QA_LIST.length];
}
